"""Inspect the workspace: list files and, if a SQLite DB exists, show its schema."""
import os
import sqlite3

print("=== Files in workspace ===")
for entry in sorted(os.listdir(".")):
    print(entry)

print("\n=== SQLite databases ===")
for entry in sorted(os.listdir(".")):
    if entry.endswith(".db") or entry.endswith(".sqlite") or entry.endswith(".sqlite3"):
        path = entry
        print(f"\n--- {path} ---")
        try:
            with sqlite3.connect(path) as conn:
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print("(no tables)")
                for (table,) in tables:
                    print(f"\nTable: {table}")
                    for row in cur.execute(f"PRAGMA table_info({table})"):
                        print(f"  col: {row}")
        except sqlite3.Error as exc:
            print(f"Could not read DB: {exc}")

